"""Build a standalone presentation from recorded research evidence."""
import base64
from datetime import datetime,timezone
import json
from pathlib import Path
import statistics

E=Path('docs/evidence');P=Path('docs/presentation');P.mkdir(exist_ok=True)
def read(name):return json.loads((E/name).read_text())
def picture(name):return '<img src="data:image/png;base64,'+base64.b64encode((E/name).read_bytes()).decode()+'" alt="Recorded research evidence">'
def slide(title,body,tag='RESEARCH UPDATE'):
 return '<section class="slide"><div class="tag">AEROROZUM · '+tag+'</div><h1>'+title+'</h1>'+body+'<footer>'+stamp+' UTC · Development research · source records retained</footer></section>'

stamp=datetime.now(timezone.utc).strftime('%d %B %Y · %H:%M')
primary=read('high-thinking-primary-first-pass.json');extra=read('high-thinking-requalified-first-pass.json');recovery=read('high-thinking-bounded-recovery.json')
labels=sum(r['report']['labelled'] for r in [primary,extra,recovery]);attempts=sum(r['actual_requests'] for r in [primary,extra,recovery])
plan=read('high-teacher-curriculum-plan.json')['seeds'][0];visual=read('visual-replications-summary.json');means=[statistics.mean(r['evaluations'][i]['micro_f2'] for r in visual['seeds']) for i in range(3)]
expanded=read('expanded-comparison-v1.json')
expanded_complete=all(s['state']=='completed' for r in expanded['seeds'] for s in r['stages'][:2])
expanded_note='The larger 2,400-image parent cohort is still being evaluated.'
if expanded_complete:
 expanded_means=[statistics.mean(r['stages'][i]['micro_f2'] for r in expanded['seeds']) for i in range(2)]
 expanded_updates='/'.join(str(r['stages'][1]['actual_updates']) for r in expanded['seeds'])
 expanded_note=f'Separate 2,400-image cohort, all three seeds: mean F2 {expanded_means[0]:.3f} after SFT → {expanded_means[1]:.3f} after guarded GRPO ({expanded_updates} actual updates).'
slides=[]
slides.append(slide('An agent that manages<br>a thermal investigation.', '<div class="columns"><div><p class="lead">Choose where to inspect. Revisit uncertainty. Reserve flight time. Build a report from captured evidence.</p><div class="cards"><div><strong>'+f'{labels:,}'+'</strong><span>qualified flight frames labeled</span></div><div><strong>4 × A100</strong><span>cloud research and inference</span></div></div><p>Harbor task + OpenCode harness + a verifier that scores complete missions from 0 to 1.</p></div><div class="visual">'+picture('thermal-model-example-v1.png')+'<p class="small">Original thermal frame with recorded model proposals; six configurations on the same image. Candidate identities remain provisional.</p></div></div>', 'THERMAL INVESTIGATION ENVIRONMENT'))
slides.append(slide('Real frames, preserved evidence.', '<div class="cards three"><div><strong>'+f'{labels:,}'+'</strong><span>schema-valid qualified-frame identities</span></div><div><strong>'+f'{attempts:,}'+'</strong><span>issued requests, including recovered failures</span></div><div><strong>36 / 36</strong><span>bounded recovery cases succeeded</span></div></div><div class="flow"><b>5 FPS sampling</b><i>→</i><b>Fresh flight telemetry</b><i>→</i><b>HIGH inference</b><i>→</i><b>Versioned raw logs</b></div><div class="columns"><div><h2>Learning inputs</h2><p>'+f"{plan['images']:,} images per seed: {plan['positive_frames']:,} positive and {plan['zero_candidate_frames']:,} explicit model-zero frames, across {plan['source_groups']} source groups."+'</p><p>162 original-manual anchors + 320 reviewed-AI anchors + 4,206 accepted-model records.</p></div><div><h2>Quality boundaries</h2><p>Whole-session splits and held-out pixel hashes are preserved. Uncertain or mixed frames remain outside this training cohort.</p><p class="small">These are machine pseudo labels, not independent physical mine confirmation. Ground intervals, unknown flight state and frame/receipt mismatches are excluded from the qualified pool.</p></div></div>'))
slides.append(slide('Three seeds show a repeatable development gain.', '<div class="wideplot">'+picture('visual-replications-v1.png')+'</div><p class="small">Mean F2: '+f'{means[0]:.3f} after SFT → {means[1]:.3f} after 48 GRPO updates → {means[2]:.3f} after 144 total GRPO updates.'+' '+expanded_note+'</p><p class="small">Same 120 reused development references: 30 original-manual, 58 reviewed-AI and 32 model-zero frames. Cohorts also differ in data size and training duration. These results measure label agreement; field generalization remains unverified. The deployed checkpoint is unchanged.</p>', 'GEMMA 12B · LANGUAGE + VISUAL PROJECTION LORA'))
slides.append(slide('Thinking level changes the labeling result.', '<div class="studyplot">'+picture('robotics-thinking-study-v1.png')+'</div><p class="small">2 prompts × 3 native thinking levels × 3 repeats × 120 development images = 2,160 completions. Equal 65,536-token caps. V2 HIGH averaged F2 0.604, versus V2 MINIMAL 0.298. Prompt selection excluded the opened test set.</p>', 'ROBOTICS API · PAIRED PROMPT STUDY'))
slides.append(slide('Flight-budget management changes the score.', '<div class="nativeplot">'+picture('native-outcomes-v1.png')+'</div><div class="cards"><div><strong>0.000</strong><span>Illustrative Carbon episode: 2 / 3 targets retrieved, 83.56 / 75 flight seconds.</span></div><div><strong>0.764</strong><span>Illustrative Argon episode: 2 / 3 retrieved, both regions covered, home in 72.516 seconds.</span></div></div><p class="small">Examples use different seeds. The grid retains every terminal outcome and marks infrastructure errors and pending cases separately. Context/output allowances differ; the native Gemma arm also changes its tool interface. The benchmark uses inserted synthetic objects in composed imagery.</p>', 'NATIVE HARBOR PLAYTHROUGHS'))
slides.append(slide('A physical day has finished solving.', '<div class="physics"><div>'+picture('physics-full-day-diagnostic-v1.png')+'</div><div><h2>24 physical hours</h2><p>2,887 adaptive surface states from the actual local 3D DuMux run.</p><p>Conservation and interface checks passed. Grid/time/domain qualification remains separate.</p><p>The larger-domain run continues. One local axisymmetric pair is numerically accepted; heterogeneous terrain and outdoor calibration remain unverified.</p><p class="small">The displayed spatial contrast is center minus surrounding-ring median, not a matched present/absent counterfactual.</p></div></div>', 'ACTUAL SOLVER OUTPUT'))
slides.append(slide('Continue the controlled comparisons.', '<div class="columns"><div><h2>Cloud comparison pipeline</h2><p>Three seeds × '+f"{plan['images']:,} HIGH-teacher images; {plan['sft_updates']:,} SFT updates per seed, then guarded GRPO."+'</p><p>Fixed early checkpoints at 0.5, 1.0 and 2.0 epochs. The first is saved and cloud-verified; training continues. Context and crop reviews retain their provenance.</p><p>Paired balanced versus 80/20 positive replay retains every source example and the four-group stop rule.</p><p class="small">All outcomes and actual update counts are retained. No automatic model deployment.</p></div><div><h2>Run the submitted task</h2><pre>bash &lt;(curl -fsSL https://136.115.179.240/start.sh)</pre><p>The wizard checks prerequisites, downloads the verified package, and asks privately for a Gemini API key.</p><p><a href="https://136.115.179.240">Live mission demo ↗</a><br><a href="https://136.115.179.240/presentation/research-overnight/index.html">Live research, thermal clips and physics animation ↗</a><br><a href="https://github.com/Yegmina/Junction_2026/tree/codex/research-replication">Source and evidence ↗</a></p></div></div>', 'SUBMISSION PACKAGE UNCHANGED'))
style='''@page{size:1280px 720px;margin:0}*{box-sizing:border-box}html,body{margin:0;background:#0b1419;color:#e8f3f2;font-family:Arial,sans-serif}.slide{position:relative;width:1280px;height:720px;overflow:hidden;padding:38px 54px 50px;break-after:page}.slide:last-child{break-after:auto}.tag{font-size:12px;letter-spacing:2px;color:#6ce5cb}h1{font-size:37px;line-height:1.13;margin:14px 0 22px;letter-spacing:-.8px}h2{font-size:24px}p{font-size:21px;line-height:1.4;color:#bad0d3;margin:14px 0}.lead{font-size:29px;line-height:1.35}.small{font-size:14px;line-height:1.35;color:#9ab5bd}.columns{display:grid;grid-template-columns:1fr 1fr;gap:34px}.cards{display:flex;gap:18px;margin:22px 0}.cards>div{flex:1;padding:20px;background:#142a33;border:1px solid #2b464f;border-radius:14px}.cards strong{display:block;font-size:37px;color:#6ce5cb;margin-bottom:9px}.cards span{display:block;font-size:18px;line-height:1.35;color:#bbd1d4}.flow{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:24px 0;padding:18px 0;color:#6ce5cb;font-size:18px}.flow i{color:#789da5}img{width:100%;height:100%;object-fit:contain}.visual{padding-top:5px}.visual>img{height:370px;background:white;border-radius:10px}.wideplot{height:405px;background:white;border-radius:12px}.studyplot{height:458px;background:white;border-radius:12px}.nativeplot{height:330px;background:white;border-radius:12px}.nativeplot+.cards{margin:14px 0}.nativeplot+.cards>div{padding:10px 18px}.nativeplot+.cards strong{font-size:28px}.nativeplot+.cards span{font-size:16px}.physics{display:grid;grid-template-columns:800px 1fr;gap:24px}.physics>div:first-child{height:495px;background:white;border-radius:10px}.physics p{font-size:19px}.physics .small{font-size:14px}pre{font-size:16px;line-height:1.5;white-space:pre-wrap;padding:20px;background:#142a33;border-radius:12px;color:#6ce5cb}a{color:#6ce5cb;text-decoration:none;font-size:18px;line-height:1.8}footer{position:absolute;bottom:18px;left:54px;right:54px;font-size:11px;color:#6c969f;border-top:1px solid #29434a;padding-top:8px}'''
html='<!doctype html><html><head><meta charset="utf-8"><title>AeroRozum · Overnight research brief</title><style>'+style+'</style></head><body>'+''.join(slides)+'</body></html>'
(P/'overnight-brief.html').write_text(html)
(E/'overnight-brief-provenance.json').write_text(json.dumps(dict(generated_at=stamp,slides=len(slides),qualified_labels=labels,issued_requests=attempts,source_evidence='docs/evidence/',metrics_invented=False,submission_unchanged=True),indent=2)+'\n')
print(json.dumps({'slides':len(slides),'labels':labels,'html_bytes':len(html.encode())}))
